tool_input.command:
cd "C:/visual projects/alpha" && T=$(cygpath -w /tmp) && cat > "$T/p3.py" <<'E'
p='tools/compute/alsched.py'
s=open(p,encoding='utf-8').read()
def rep(a,b,cnt=1):
    global s
    assert s.count(a)==cnt,(a,s.count(a)); s=s.replace(a,b)
# submit
rep('def submit(cls, name, cores, mem, disk, cwd, cmd, max_runtime, prio=5, io=""):','def submit(cls, name, cores, mem, disk, cwd, cmd, max_runtime, prio=5, io="", iso=0):')
rep('prio=prio, io=io, max_runtime=max_runtime, active_s=0, state="queued", t_submit=time.time(), cpus=[])','prio=prio, io=io, max_runtime=max_runtime, active_s=0, state="queued", t_submit=time.time(), cpus=[])\n    if iso and cls == "measure":\n        j["iso"] = iso')
rep('        p.add_argument("--cwd", default=os.getcwd())\n        p.add_argument("--prio"','        p.add_argument("--cwd", default=os.getcwd())\n        p.add_argument("--iso", type=int, default=0, help="замер: K физических ядер (оба SMT-соседа) без остановки производства (п.3); 0 — окно на весь сервер")\n        p.add_argument("--prio"')
rep('parse_dur(o.max_runtime), o.prio, o.io)','parse_dur(o.max_runtime), o.prio, o.io, o.iso)')
# win_begin / win_end
rep('''        return dict(t=time.time(), cpu=self.cpu_host(), disk=b, ios=n, units=set(self.foreign_units(j)),''','''        iso = j.get("iso_cpus")
        return dict(t=time.time(), cpu=self.cpu_cores(iso) if iso else self.cpu_host(), disk=b, ios=n, units=set() if iso else set(self.foreign_units(j)),''')
rep('''        d = dict(wall_s=t1 - s0["t"], cpu_s=self.cpu_host() - s0["cpu"],''','''        iso = j.get("iso_cpus")     # изолированное окно: чужое ЦП — на ядрах замера, посторонние юниты на других ядрах не помеха
        d = dict(wall_s=t1 - s0["t"], cpu_s=(self.cpu_cores(iso) if iso else self.cpu_host()) - s0["cpu"],''')
rep('''                 foreign_units=s0["units"] | set(self.foreign_units(j)))''','''                 foreign_units=set() if iso else s0["units"] | set(self.foreign_units(j)))''')
rep('''        ok, why = judge_window(d)
        if ok and d["wall_s"] >= 600:''','''        ok, why = judge_window(d, ncpu=len(iso) if iso else NCPU)
        if iso and ok:       # П4: OOM-убийств за окно нет
            ok_oom = self.oom_kills() - s0.get("oom", 0)
            if ok_oom:
                ok, why = False, [f"oom_kill в окне: {ok_oom}"]
        if ok and d["wall_s"] >= 600:''')
rep('''swap=self.swap_pages())

    def win_end''','''swap=self.swap_pages(), oom=self.oom_kills())

    def win_end''')
rep('''    def cpu_host(self):''','''    @staticmethod
    def cpu_cores(cpus):
        """ЦП-секунды (без idle/iowait) по перечисленным ядрам — /proc/stat cpuN."""
        t = 0
        for l in open("/proc/stat"):
            k = l.split()
            if k[0].startswith("cpu") and k[0] != "cpu" and int(k[0][3:]) in cpus:
                v = [int(x) for x in k[1:]]
                t += sum(v) - v[3] - v[4]
        return t / os.sysconf("SC_CLK_TCK")

    @staticmethod
    def oom_kills():
        return sum(int(l.split()[1]) for l in open("/proc/vmstat") if l.startswith("oom_kill "))

    def cpu_host(self):''')
# daemon restart
rep('''    if mw:                       # перезапуск демона в окне замера: производство не размораживаем, окно недействительно
        core.frozen = True
        for j in mw:''','''    if mw:                       # перезапуск демона в окне замера: производство не размораживаем, окно недействительно
        core.frozen = any(not j.get("iso_cpus") for j in mw)    # изолированное окно производство не морозило
        for j in mw:''')
open(p,'w',encoding='utf-8',newline='').write(s)
E
python "$T/p3.py" && python -c "import ast;ast.parse(open('tools/compute/alsched.py',encoding='utf-8').read())" && echo ok; grep -n "else:\s*$" tools/compute/alsched.py | sed -n 1,0p; sed -n '/перезапуск демона в окне/,/be.thaw_all()/p' tools/compute/alsched.py | cut -c1-120
